import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CfmV7b-z.js";const p=JSON.parse('{"title":"Cachier","description":"","frontmatter":{"title":"Cachier"},"headers":[],"relativePath":"api/lib/cachier.md","filePath":"api/lib/cachier.md"}'),n={name:"api/lib/cachier.md"};function d(i,e,c,s,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="cachier" tabindex="-1">Cachier <a class="header-anchor" href="#cachier" aria-label="Permalink to &quot;Cachier&quot;">​</a></h1><h2 id="new-cachier" tabindex="-1"><code>new Cachier([opts], [readFormatter], [writeFormatter], [log])</code> <a class="header-anchor" href="#new-cachier" aria-label="Permalink to &quot;`new Cachier([opts], [readFormatter], [writeFormatter], [log])` {#new-cachier}&quot;">​</a></h2><p>The default persistence cache manager that uses a simple object mapping for <a href="#cachier-read">Cachier.read</a>/<a href="#cachier-write">Cachier.write</a> operations. All caching is maintained in-memory. Template, partial and context <a href="#cachier-read">Cachier.read</a> operations use the standard Fetch API in supported Node.js and browser runtimes to capture partial template content. Compiled template <a href="#cachier-read">Cachier.read</a> operations are handled via <em>dynamic</em> <code>import</code>/<code>require</code> (if used). <a href="#cachier-write">Cachier.write</a> operations are typically written to memory, but can also be configured to <code>POST</code> template, partials and/or context over HTTP/S.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>[opts]</td><td><code>TemplateOpts</code></td><td>the <a href="./template-options#new-templateopts">TemplateOpts</a></td></tr><tr><td>[readFormatter]</td><td><code>function</code></td><td>The <code>function(string, readFormatOptions)</code> that will return a formatted string for <strong>reading</strong><br>data using the <code>options.readFormatOptions</code> from <a href="./template-options#new-templateopts">TemplateOpts</a> as the formatting options. Typically reads are for <strong>HTML</strong><br><em>minification</em> and/or <em>beautifying</em>. <strong>NOTE: Use with caution as syntax errors may result depending on the formatter used and the<br>complexity of the data being formatted!</strong></td></tr><tr><td>[writeFormatter]</td><td><code>function</code></td><td>The <code>function(string, writeFormatOptions)</code> that will return a formatted string for <strong>writting</strong><br>data using the <code>options.writeFormatOptions</code> from <a href="./template-options#new-templateopts">TemplateOpts</a> as the formatting options. Typically reads are for <strong>JS</strong><br><em>minification</em> and/or <em>beautifying</em>. <strong>NOTE: Use with caution as syntax errors may result depending on the formatter used and the<br>complexity of the data being formatted!</strong></td></tr><tr><td>[log]</td><td><code>Object</code></td><td>The log for handling logging output</td></tr><tr><td>[log.debug]</td><td><code>function</code></td><td>A function that will accept <strong>debug</strong> level logging messages (i.e. <code>debug(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.info]</td><td><code>function</code></td><td>A function that will accept <strong>info</strong> level logging messages (i.e. <code>info(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.warn]</td><td><code>function</code></td><td>A function that will accept <strong>warning</strong> level logging messages (i.e. <code>warn(&#39;some message to log&#39;)</code>)</td></tr><tr><td>[log.error]</td><td><code>function</code></td><td>A function that will accept <strong>error</strong> level logging messages (i.e. <code>error(&#39;some message to log&#39;)</code>)</td></tr></tbody></table><h3 id="cachier-registerhelper" tabindex="-1"><code>cachier.registerHelper(func)</code> <a class="header-anchor" href="#cachier-registerhelper" aria-label="Permalink to &quot;`cachier.registerHelper(func)` {#cachier-registerhelper}&quot;">​</a></h3><p>Registers a <em>directive</em> function that can be used within template <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Template_literals#Expression_interpolation" target="_blank" rel="noreferrer">interpolations</a></p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>func</td><td><code>function</code></td><td>A <strong>named</strong> <code>function</code> that has no external scope dependencies/closures other than those exposed<br>via templates during rendering</td></tr></tbody></table><h3 id="cachier-unregister" tabindex="-1"><code>cachier.unregister(name)</code> <a class="header-anchor" href="#cachier-unregister" aria-label="Permalink to &quot;`cachier.unregister(name)` {#cachier-unregister}&quot;">​</a></h3><p>Unregisters a partial template from cache</p><p><strong>Async:</strong> yes</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The template name that uniquely identifies the template content</td></tr></tbody></table><h3 id="cachier-registerpartial" tabindex="-1"><code>cachier.registerPartial(name, contentOrParams, [extension=options.defaultExtension])</code> ⇒ <code>String</code> <a class="header-anchor" href="#cachier-registerpartial" aria-label="Permalink to &quot;`cachier.registerPartial(name, contentOrParams, [extension=options.defaultExtension])` ⇒ `String` {#cachier-registerpartial}&quot;">​</a></h3><p>Registers and stores a partial template <strong>in-memory</strong>. Use <a href="#cachier-register">Cachier.register</a> to write partials to cache (<a href="#new-cachier">Cachier</a>)</p><p><strong>Async:</strong> yes</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td></td><td>The <strong>raw</strong> template name (i.e. not from <a href="#cachier-readwritename">Cachier.readWriteName</a>)</td></tr><tr><td>contentOrParams</td><td><code>String</code> | <code>URLSearchParams</code></td><td></td><td>Either the partial template content <strong>string</strong> to register <em>or</em> the<br><code>URLSearchParams</code> that will be passed during the content <code>read</code></td></tr><tr><td>[extension=options.defaultExtension]</td><td><code>String</code></td><td>options.defaultExtension</td><td>Optional override for a file extension designation for the partial</td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>String</code> — The partial content</li></ul><h3 id="cachier-getregistered" tabindex="-1"><code>cachier.getRegistered(name, [params], [extension=options.defaultExtension])</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-getregistered" aria-label="Permalink to &quot;`cachier.getRegistered(name, [params], [extension=options.defaultExtension])` ⇒ `Object` {#cachier-getregistered}&quot;">​</a></h3><p>Retrieves a template, partial or context that resides <strong>in-memory</strong>.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td></td><td>The <strong>raw</strong> template name (i.e. not from <a href="#cachier-readwritename">Cachier.readWriteName</a>)</td></tr><tr><td>[params]</td><td><code>URLSearchParams</code></td><td></td><td>Any parameters designated during <a href="#cachier-registerpartial">Cachier.registerPartial</a></td></tr><tr><td>[extension=options.defaultExtension]</td><td><code>String</code></td><td>options.defaultExtension</td><td>Optional override for a file extension designation<br>for the template, partial or context designated during <a href="#cachier-registerpartial">Cachier.registerPartial</a></td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — A copy of the generated data from <a href="#cachier-registerpartial">Cachier.registerPartial</a></li></ul><h3 id="cachier-register" tabindex="-1"><code>cachier.register([data], [read], [write])</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-register" aria-label="Permalink to &quot;`cachier.register([data], [read], [write])` ⇒ `Object` {#cachier-register}&quot;">​</a></h3><p>Registers and <strong>caches</strong> the template, one or more partial templates and/or context JSON.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>[data]</td><td><code>Array.&lt;Object&gt;</code></td><td>The template, partials and/or context to register.</td></tr><tr><td>data[].name</td><td><code>String</code></td><td>The name that uniquely identifies the template, partial or context</td></tr><tr><td>[data[].content]</td><td><code>String</code></td><td>The raw content that will be registered. Omit when <code>read === true</code> to read content from cache.</td></tr><tr><td>[data[].params]</td><td><code>URLSearchParams</code></td><td>The <code>URLSearchParams</code> that will be passed during the content <code>read</code><br>(<strong>ignored when <code>content</code> is specified</strong>).</td></tr><tr><td>[data[].extension]</td><td><code>String</code></td><td>Optional override for a file extension designated for a template, partial or context.</td></tr><tr><td>[read]</td><td><code>Boolean</code></td><td>When <code>true</code>, an attempt will be made to also <a href="#cachier-read">Cachier.read</a> the template, partials and context that<br><strong>do not have</strong> a <code>content</code> property set.</td></tr><tr><td>[write]</td><td><code>Boolean</code></td><td>When <code>true</code>, an attempt will be made to also <a href="#cachier-write">Cachier.write</a> the template, partials and context that<br><strong>have</strong> a <code>content</code> property set.</td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><p><code>Object</code> — An object that contains the registration results:</p></li><li><p><code>data</code> The object that contains the template, partial fragments and/or context that have been registered</p><ul><li><code>name</code> The name that uniquely identifies the template, partial or context</li><li><code>content</code> The raw content of the template, partial or context</li><li><code>extension</code> The template file extension designation</li><li><code>params</code> The URLSearchParams passed during the <strong>initial</strong> content read</li><li><code>fromRead</code> A flag that indicates that the data was set from a read operation</li></ul></li></ul><h3 id="cachier-compile" tabindex="-1"><code>cachier.compile(name, [template], [params], [extension])</code> ⇒ <code>function</code> <a class="header-anchor" href="#cachier-compile" aria-label="Permalink to &quot;`cachier.compile(name, [template], [params], [extension])` ⇒ `function` {#cachier-compile}&quot;">​</a></h3><p>Compiles a locally sandboxed <code>async</code> template rendering function and when applicable, stores the function in cache</p><p><strong>Async:</strong> yes</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The template name that uniquely identifies the primary template content</td></tr><tr><td>[template]</td><td><code>String</code> | <code>Boolean</code></td><td>The raw template content, <code>true</code> to read from cache before compilation.<br>Omit to load the template content from cache when the returned rendering function is called.</td></tr><tr><td>[params]</td><td><code>URLSearchParams</code></td><td>Any URL search parmeters that will be passed when capturing the primary <code>template</code> and/or <code>context</code> when needed</td></tr><tr><td>[extension]</td><td><code>String</code></td><td>The file extension designation for the template</td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> — The return function from <a href="./sandbox#sandbox-compile">Sandbox.compile</a></li></ul><h3 id="cachier-read" tabindex="-1"><code>cachier.read(name, [forContent], [extension], [params])</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-read" aria-label="Permalink to &quot;`cachier.read(name, [forContent], [extension], [params])` ⇒ `Object` {#cachier-read}&quot;">​</a></h3><p>Reads either template content or template code from internal cache. When <code>options.partialsURL</code> is set to an HTTP/S URL and the read is for partial content, a <code>GET</code> call to the standard Fetch API is made. The partial <code>name</code> will be appended to <code>options.partialsURL</code> (e.g. <code>https://example.com/some/id.html</code> where <code>some/id.html</code> is the the partial&#39;s <a href="#cachier-readwritename">Cachier.readWriteName</a> and <code>options.partialsURL</code> is set to <code>https://example.com</code>). When <code>options.partialsURL</code> is omitted <em>reading</em> of template partial content will be limited to <em>reading</em> from memory. Compiled template source code is <em>always</em><em>read</em> from memory <strong>only</strong>.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The template name that uniquely identifies the template content</td></tr><tr><td>[forContent]</td><td><code>Boolean</code></td><td><code>true</code> to read a template content, <code>false</code> to read the template source code</td></tr><tr><td>[extension]</td><td><code>String</code></td><td>The file extension designation (only used when <code>forContent</code> is truthy)</td></tr><tr><td>[params]</td><td><code>URLSearchParams</code></td><td>The <code>URLSearchParams</code> to pass for the read (only used when <code>forContent</code> is truthy)</td></tr></tbody></table><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — An object read from cache that contains either the template content or module.</li></ul><p>Returned template content properties:</p><ul><li><code>name</code> The template name that uniquely identifies the template content</li><li><code>content</code> The template content</li><li><code>extension</code> The template file extension designation</li></ul><p>Returned module properties:</p><ul><li><code>name</code> The template name that uniquely identifies the template content</li><li><code>func</code> The module function generated from the code</li></ul><h3 id="cachier-write" tabindex="-1"><code>cachier.write(name, data, [forContent], [extension], [params])</code> ⇒ <code>function</code> | <code>undefined</code> <a class="header-anchor" href="#cachier-write" aria-label="Permalink to &quot;`cachier.write(name, data, [forContent], [extension], [params])` ⇒ `function` \\| `undefined` {#cachier-write}&quot;">​</a></h3><p>Writes either template content or template code from internal cache. When <code>options.partialsURL</code> is set to an HTTP/S URL and the write is for partial content, a <code>POST</code> call to the standard Fetch API is made. The partial <code>name</code> will be appended to <code>options.partialsURL</code> (e.g. <code>https://example.com/some/id.html</code> where <code>some/id.html</code> is the the partial&#39;s <a href="#cachier-readwritename">Cachier.readWriteName</a> and <code>options.partialsURL</code> is set to <code>https://example.com</code>). When <code>options.partialsURL</code> is omitted <em>writting</em> of template partial content will be limited to <em>writes</em> to memory. Compiled template source code is <em>always</em><em>written</em> to memory <strong>only</strong>.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The template name that uniquely identifies the template content</td></tr><tr><td>data</td><td><code>String</code> | <code>function</code></td><td>The data to write. For content, <code>data</code> should be a string. Otherwise <code>data</code> should be a function or<br>a function string.</td></tr><tr><td>[forContent]</td><td><code>Boolean</code></td><td><code>true</code> to read a template content, <code>false</code> to read the template source code</td></tr><tr><td>[extension]</td><td><code>String</code></td><td>The file extension designation (only used when <code>forContent</code> is truthy)</td></tr><tr><td>[params]</td><td><code>URLSearchParams</code></td><td>The <code>URLSearchParams</code> to pass for the write (only used when <code>forContent</code> is truthy)</td></tr></tbody></table><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> | <code>undefined</code> — Optionally return the compiled/written module function</li></ul><h3 id="cachier-options" tabindex="-1"><code>cachier.options</code> ⇒ <code>TemplateOpts</code> <a class="header-anchor" href="#cachier-options" aria-label="Permalink to &quot;`cachier.options` ⇒ `TemplateOpts` {#cachier-options}&quot;">​</a></h3><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>TemplateOpts</code> — The template compile options</li></ul><h3 id="cachier-metadata" tabindex="-1"><code>cachier.metadata</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-metadata" aria-label="Permalink to &quot;`cachier.metadata` ⇒ `Object` {#cachier-metadata}&quot;">​</a></h3><p><strong>Access:</strong> protected</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The compilation metadata that will be passed into <a href="./sandbox#sandbox-compile">Sandbox.compile</a></li></ul><h3 id="cachier-readformatter" tabindex="-1"><code>cachier.readFormatter</code> ⇒ <code>function</code> <a class="header-anchor" href="#cachier-readformatter" aria-label="Permalink to &quot;`cachier.readFormatter` ⇒ `function` {#cachier-readformatter}&quot;">​</a></h3><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> — The <strong>read</strong> formatting function that takes 1 or 2 arguments with the first being the content that will be formatted and the second being <code>options.readFormatOptions</code></li></ul><h3 id="cachier-writeformatter" tabindex="-1"><code>cachier.writeFormatter</code> ⇒ <code>function</code> <a class="header-anchor" href="#cachier-writeformatter" aria-label="Permalink to &quot;`cachier.writeFormatter` ⇒ `function` {#cachier-writeformatter}&quot;">​</a></h3><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> — The <strong>write</strong> formatting function that takes 1 or 2 arguments with the first being the content that will be formatted and the second being <code>options.writeFormatOptions</code></li></ul><h3 id="cachier-log" tabindex="-1"><code>cachier.log</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-log" aria-label="Permalink to &quot;`cachier.log` ⇒ `Object` {#cachier-log}&quot;">​</a></h3><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The optional log used by the <a href="#new-cachier">Cachier</a></li></ul><h3 id="cachier-stats" tabindex="-1"><code>cachier.stats</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-stats" aria-label="Permalink to &quot;`cachier.stats` ⇒ `Object` {#cachier-stats}&quot;">​</a></h3><p>Returns a snapshot of cache activity and current cache size.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — Cache statistics.</li></ul><h3 id="cachier-resetstats" tabindex="-1"><code>cachier.resetStats()</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-resetstats" aria-label="Permalink to &quot;`cachier.resetStats()` ⇒ `Object` {#cachier-resetstats}&quot;">​</a></h3><p>Resets cumulative cache counters while retaining current entry and byte totals.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The reset cache statistics.</li></ul><h3 id="cachier-clearmemory" tabindex="-1"><code>cachier.clearMemory()</code> <a class="header-anchor" href="#cachier-clearmemory" aria-label="Permalink to &quot;`cachier.clearMemory()` {#cachier-clearmemory}&quot;">​</a></h3><p>Clears in-memory template content and compiled renderers.</p><p><strong>Async:</strong> yes</p><h3 id="cachier-clear" tabindex="-1"><code>cachier.clear([all=false])</code> <a class="header-anchor" href="#cachier-clear" aria-label="Permalink to &quot;`cachier.clear([all=false])` {#cachier-clear}&quot;">​</a></h3><p>Clears the cache.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>[all=false]</td><td><code>Boolean</code></td><td>false</td><td>Reserved for persistence implementations that can clear unassociated cache instances.</td></tr></tbody></table><h3 id="cachier-close" tabindex="-1"><code>cachier.close()</code> <a class="header-anchor" href="#cachier-close" aria-label="Permalink to &quot;`cachier.close()` {#cachier-close}&quot;">​</a></h3><p>Releases in-memory cache resources. Persistence implementations may extend this method to close additional resources.</p><p><strong>Async:</strong> yes</p><h3 id="cachier-modules" tabindex="-1"><code>cachier.modules(optional)</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-modules" aria-label="Permalink to &quot;`cachier.modules(optional)` ⇒ `Object` {#cachier-modules}&quot;">​</a></h3><p><strong>Async:</strong> yes</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>optional</td><td><code>TemplateOpts</code> | <code>function</code></td><td>Either the <a href="./template-options#new-templateopts">TemplateOpts</a> or a function that takes a<br>single name argument and returns the option value</td></tr></tbody></table><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The object that contains the modules used by the <a href="#new-cachier">Cachier</a> implementation</li></ul><h3 id="cachier-operations" tabindex="-1"><code>cachier.operations</code> ⇒ <code>Object</code> | <code>Array.&lt;Object&gt;</code> | <code>function</code> | <code>function</code> | <code>function</code> | <code>Array.&lt;function()&gt;</code> <a class="header-anchor" href="#cachier-operations" aria-label="Permalink to &quot;`cachier.operations` ⇒ `Object` \\| `Array.&lt;Object&gt;` \\| `function` \\| `function` \\| `function` \\| `Array.&lt;function()&gt;` {#cachier-operations}&quot;">​</a></h3><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> | <code>Array.&lt;Object&gt;</code> — [operations] One or more operation objects that will handle render-time reads/writes</li><li><code>function</code> — [operations[].read] The reader is an <code>async function</code> responsible for reading partial template content/modules/etc during render-time when a partial template cannot be found within <code>includes</code>. When <code>options.cacheRawTemplates</code> is <em>truthy</em> an attempt will be made to add any missing/read partials into <code>storage.data</code> in order to prevent unnecessary template partial reads for repeated includes. Read functions should not reference any external scope other than the global object space. The following arguments will be passed:</li></ul><ol><li><em>{String}</em> <code>name</code> The name of the partial that will be read. The read function may be invoked without a <em>name</em> parameter when the intent is to capture all partials in a single read opteration that will be included.</li><li><em>{String}</em> <code>path</code> The path to the partial that will be read. The read function may be invoked without a <em>path</em> parameter when the intent is to capture all partials in a single read opteration that will be included.</li><li><em>{String}</em> <code>ext</code> The path file extension to the partial that will be read. The read function may be invoked without an <em>ext</em> parameter when the intent is to capture all partials in a single read opteration that will be included.</li><li><em>{Boolean}</em> <code>forContent</code> The flag indicating that the read is for content. Otherwise, the read is for rendering functions.</li><li><em>{(TemplateOpts | Function(name:String)😗)}</em> <code>optional</code> Either the <a href="./template-options#new-templateopts">TemplateOpts</a> or a function that takes a single name argument and returns the option value.</li><li><em>{URLSearchParams}</em> <code>[params]</code> The URLSearchParams that should be used during the read</li><li><em>{Object}</em> <code>storage</code> The storage object that can contain metadata for read operations and should contain a <strong>data</strong> object that stores each of the read paratial template content/metadata.</li><li><em>{Function}</em> <code>[formatter]</code> The function that will format reads/writes during include discovery (if any). The formatting function takes 1 or 2 arguments with the first being the content that will be formatted and the second being <code>options.readFormatOptions</code> for reads and <code>options.writeFormatOptions</code> for writes. The returned result should be a valid string.</li><li><em>{Boolean}</em> <code>[close]</code> A flag indicating whether or not any resources used during the read should be closed/cleaned up after the read completes. Closure may be dependent upon the policy set on the options.</li><li><em>{Object}</em> <code>[log]</code> A logger that can contain functions for each of the following: <code>error</code>/<code>warn</code>/<code>info</code>/<code>debug</code>.</li></ol><p>Read functions can return the partial template content and/or it can be set on the <code>storage.data</code>. Returning <code>true</code> will stop any further rendering from processing resulting in the rendering function returning a <em>blank</em> string.</p><ul><li><code>function</code> — [operations[].write] The write function that will be used for writting newly discovered template sources. Accepts the same arguments as <code>operations[].read</code> and all <em>scoped</em> functions will be available. Can return a <strong>rendering</strong> function that will prevent further iteration of any subsequent <code>operations[].write</code> invocations.</li><li><code>function</code> — [operations[].finish] An <code>async function</code> that can perform cleanup tasks for a reader. Arguments passed are <code>storage</code>, <code>optional</code> and <code>log</code> as described for <code>operations[].read</code>.</li><li><code>Array.&lt;function()&gt;</code> — [operations[].scopes] Zero or more functions that will be in scope when the read function is called. Scoped functions can assit with complex read/write operations that can benefit from separate supporting functions. For example, <code>[myFunc(){}]</code> could be referenced like <code>async function myReader(){ myFunc(); ... }</code>.</li></ul><h3 id="cachier-readwritename" tabindex="-1"><code>cachier.readWriteName(name, optional, [params], store, forContent, [extension], forContext)</code> ⇒ <code>String</code> <a class="header-anchor" href="#cachier-readwritename" aria-label="Permalink to &quot;`cachier.readWriteName(name, optional, [params], store, forContent, [extension], forContext)` ⇒ `String` {#cachier-readwritename}&quot;">​</a></h3><p>Converts template names into a full path name consumable by <code>read</code>/<code>write</code> oprtations. Each function from <a href="#cachier-readwritenames">Cachier.readWriteNames</a> will be executed in order using the same arguments as <a href="#cachier-readwritename">Cachier.readWriteName</a> as well as an additional last agument being the return value from the previous function invocation.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The name of the template, partial or context that will be converted into a name suitable for a read operation</td></tr><tr><td>optional</td><td><code>TemplateOpts</code> | <code>function</code></td><td>Either the <a href="./template-options#new-templateopts">TemplateOpts</a> or a function that takes a single name<br>argument and returns the option value</td></tr><tr><td>[params]</td><td><code>URLSearchParams</code></td><td>The parameters that should be used in the converted name</td></tr><tr><td>store</td><td><code>Object</code></td><td>The storage object that can contain metadata used by naming operations</td></tr><tr><td>forContent</td><td><code>Boolean</code></td><td>The flag indicating if the converted name is being used to capture partials</td></tr><tr><td>[extension]</td><td><code>String</code></td><td>The file extension override for the converted name (omit to use the default extension set in the options)</td></tr><tr><td>forContext</td><td><code>Boolean</code></td><td>The flag indicating if the converted name is being used to capture context</td></tr></tbody></table><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>String</code> — The full template name</li></ul><h3 id="cachier-readwritenames" tabindex="-1"><code>cachier.readWriteNames</code> ⇒ <code>Object</code> | <code>Object</code> | <code>Object</code> <a class="header-anchor" href="#cachier-readwritenames" aria-label="Permalink to &quot;`cachier.readWriteNames` ⇒ `Object` \\| `Object` \\| `Object` {#cachier-readwritenames}&quot;">​</a></h3><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — <code>namers</code> One or more async functions responsible for formatting template names into a full path name consumable by <code>read</code>/<code>write</code> oprtations</li><li><code>Object</code> — <code>namers.namer</code> The default naming function</li><li><code>Object</code> — <code>namers.namerSuper</code> The naming function to use when a <a href="#cachier-operations">Cachier.operations</a> function throws an error. The next reader called in the <a href="#cachier-operations">Cachier.operations</a> list will use the name generated by this reader.</li></ul><h4 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h4><ul><li><a href="#cachier-readwritename">Cachier.readWriteName</a> for parameter details</li></ul><h3 id="cachier-contenturl" tabindex="-1"><code>Cachier.contentURL(name, opts)</code> ⇒ <code>Object</code> <a class="header-anchor" href="#cachier-contenturl" aria-label="Permalink to &quot;`Cachier.contentURL(name, opts)` ⇒ `Object` {#cachier-contenturl}&quot;">​</a></h3><p>Extracts the proper URL and option name used for a particular template, partial or context</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>name</td><td><code>String</code></td><td>The template, partial or context name</td></tr><tr><td>opts</td><td><code>TemplateOpts</code></td><td>The template options</td></tr></tbody></table><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The extracted content that contains a <code>url</code> property and a <code>optionName</code> that describes the option used for the URL</li></ul><h3 id="cachier-waiter" tabindex="-1"><code>Cachier.waiter(proms, [errMsg=&#39;One or more pomises failed&#39;], [capture=true])</code> ⇒ <code>Array</code> | <code>undefined</code> <a class="header-anchor" href="#cachier-waiter" aria-label="Permalink to &quot;`Cachier.waiter(proms, [errMsg=&#39;One or more pomises failed&#39;], [capture=true])` ⇒ `Array` \\| `undefined` {#cachier-waiter}&quot;">​</a></h3><p>Waits for promises to finish and throws commulative errors into a single meaningful stack while continuing to process subsequent promises in the array. When an error is thrown and <code>capture === true</code>, it will also contain a <code>results</code> property that contains either each result from an awaited promise or an error thrown when waiting for the promise to complete.</p><p><strong>Async:</strong> yes</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>proms</td><td><code>Array.&lt;Promise&gt;</code></td><td></td><td>The promises to wait for.</td></tr><tr><td>[errMsg=&#39;One or more pomises failed&#39;]</td><td><code>String</code></td><td>&#39;One or more pomises failed&#39;</td><td>The message to use when any errors occur.</td></tr><tr><td>[capture=true]</td><td><code>Boolean</code></td><td>true</td><td>When <code>true</code> each promise results/errors will be captured and returned. Otherwise,<br>nothing will be captured</td></tr></tbody></table><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Array</code> | <code>undefined</code> — When <code>capture === true</code>, the awaited promise results are retuend. When an error occurs, the value at the given index will contain the error instead. When <code>capture !== true</code> nothing is captured/returned.</li></ul>',132)])])}const u=t(n,[["render",d]]);export{p as __pageData,u as default};
